begin;
alter table public.company_settings add column activate_multiple_currencies boolean not null default false;
create table public.crm_currency_codes(code text primary key,name text not null);
create table public.crm_currencies(
 id uuid primary key default gen_random_uuid(),currency text not null unique references public.crm_currency_codes,
 conversion_rate numeric(10,4) not null,decimal_places integer not null default 2,is_default boolean not null default false,is_active boolean not null default true,
 created_by_id uuid references public.user_profiles on delete set null,updated_by_id uuid references public.user_profiles on delete set null,updated_at timestamptz not null default now(),
 check(not is_default or conversion_rate=1)
);
create unique index currency_single_default on public.crm_currencies(is_default) where is_default;
create table public.crm_currency_rates(id uuid primary key default gen_random_uuid(),currency_id uuid not null references public.crm_currencies on delete cascade,conversion_rate numeric(10,4) not null,start_date date not null,created_by_id uuid references public.user_profiles on delete set null,unique(currency_id,start_date));
create index currency_rates_date_idx on public.crm_currency_rates(start_date,currency_id);
create table public.crm_currency_rebases(id uuid primary key default gen_random_uuid(),actor_id uuid references public.user_profiles on delete set null,created_at timestamptz not null default now(),old_currency text not null,new_currency text not null,previous_state jsonb not null);
insert into public.permissions(id,module,action,description) values
 ('currencies.view','currencies','view','View configured company currencies'),('currencies.create','currencies','create','Add company currencies'),('currencies.update','currencies','update','Edit company conversion rates and precision'),('currencies.delete','currencies','delete','Delete non-default currencies'),
 ('currency_rates.view','currency_rates','view','View dated currency rates'),('currency_rates.create','currency_rates','create','Create dated currency rates') on conflict(id) do nothing;
