alter table public.crm_currency_codes enable row level security;
alter table public.crm_currencies enable row level security;
alter table public.crm_currency_rates enable row level security;
alter table public.crm_currency_rebases enable row level security;
create policy currency_codes_read on public.crm_currency_codes for select to authenticated using(public.is_active_employee());
create policy currency_read on public.crm_currencies for select to authenticated using(public.has_effective_permission(auth.uid(),'currencies.view'));
create policy dated_rates_read on public.crm_currency_rates for select to authenticated using(public.has_effective_permission(auth.uid(),'currencies.view') and public.has_effective_permission(auth.uid(),'currency_rates.view'));
create policy rebase_read on public.crm_currency_rebases for select to authenticated using(public.has_effective_permission(auth.uid(),'currencies.view') and public.has_effective_permission(auth.uid(),'currency_rates.view'));
revoke all on public.crm_currency_codes,public.crm_currencies,public.crm_currency_rates,public.crm_currency_rebases from public,anon,authenticated;
grant select on public.crm_currency_codes,public.crm_currencies,public.crm_currency_rates,public.crm_currency_rebases to authenticated;

create function public.set_multiple_currency_enabled(p_enabled boolean) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare configured_code text; begin
 if p_enabled is null or not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),'settings.update') then raise exception 'Permission denied' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(180102,1);
 select currency into configured_code from public.company_settings where id=1 for update;
 if not found then raise exception 'Company settings unavailable' using errcode='P0002'; end if;
 if p_enabled and not exists(select 1 from public.crm_currencies where is_default) then
  if not exists(select 1 from public.crm_currency_codes where code=configured_code) then raise exception 'Configure a supported company currency before enabling Multiple Currency' using errcode='23514'; end if;
  insert into public.crm_currencies(currency,conversion_rate,is_default,created_by_id,updated_by_id) values(configured_code,1,true,auth.uid(),auth.uid());
 end if;
 update public.company_settings set activate_multiple_currencies=p_enabled where id=1;
end $$;
create function public.save_company_currency(p_id uuid,p_currency text,p_rate text,p_decimal_places integer) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare result_id uuid; current public.crm_currencies; rate numeric;begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),case when p_id is null then 'currencies.create' else 'currencies.update' end) then raise exception 'Permission denied' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(180102,1);
 if not exists(select 1 from public.company_settings where id=1 and activate_multiple_currencies) then raise exception 'Enable Multiple Currency first' using errcode='23514'; end if;
 if p_decimal_places is null then raise exception 'Decimal Places is required' using errcode='23514'; end if;
 if p_id is not null then select * into current from public.crm_currencies where id=p_id for update;if not found then raise exception 'Currency unavailable' using errcode='P0002'; end if;end if;
 if p_id is not null and p_currency is distinct from current.currency then raise exception 'Currency identity cannot be edited' using errcode='23514'; end if;
 if p_id is not null and current.is_default then rate=1;
 else
  p_rate=btrim(p_rate);
  if p_rate is null or p_rate !~ '^-?[0-9]{1,6}(\.[0-9]{1,4})?$' then raise exception 'Conversion Rate must fit the source decimal(10,4) field' using errcode='23514'; end if;
  rate=p_rate::numeric;
 end if;
 if p_id is null then
  insert into public.crm_currencies(currency,conversion_rate,decimal_places,created_by_id,updated_by_id) values(p_currency,rate,p_decimal_places,auth.uid(),auth.uid()) returning id into result_id;
 else update public.crm_currencies set conversion_rate=rate,decimal_places=p_decimal_places,updated_by_id=auth.uid(),updated_at=now() where id=p_id returning id into result_id;end if;
 return result_id;
end $$;
create function public.delete_company_currency(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare is_base boolean;begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),'currencies.delete') then raise exception 'Permission denied' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(180102,1);select is_default into is_base from public.crm_currencies where id=p_id for update;
 if not found then raise exception 'Currency unavailable' using errcode='P0002';end if;
 if is_base then raise exception 'Default Currency can not delete' using errcode='23514';end if;
 delete from public.crm_currencies where id=p_id;
end $$;
create function public.save_company_exchange_rates(p_rates jsonb,p_start_date date default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare row record; rid uuid; rate numeric; input text; expected integer;begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),case when p_start_date is null then 'currencies.update' else 'currency_rates.create' end) then raise exception 'Permission denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(180102,1);
 if not exists(select 1 from public.company_settings where id=1 and activate_multiple_currencies) then raise exception 'Enable Multiple Currency first' using errcode='23514';end if;
 select count(*) into expected from public.crm_currencies where not is_default;
 if p_rates is null or jsonb_typeof(p_rates)<>'object' or (select count(*) from jsonb_object_keys(p_rates))<>expected or expected=0 or expected>500 then raise exception 'Provide exactly one rate for each non-default currency' using errcode='23514';end if;
 for row in select id,currency from public.crm_currencies where not is_default order by id for update loop
  input=btrim(p_rates->>row.id::text);
  if input is null or input !~ '^-?[0-9]{1,4}(\.[0-9]{1,6})?$' or jsonb_typeof(p_rates->row.id::text)<>'string' then raise exception 'Invalid conversion rate' using errcode='23514';end if;
  rate=input::numeric;
  if p_start_date is null then update public.crm_currencies set conversion_rate=rate,updated_by_id=auth.uid(),updated_at=now() where id=row.id;
  else insert into public.crm_currency_rates(currency_id,conversion_rate,start_date,created_by_id) values(row.id,rate,p_start_date,auth.uid());end if;
 end loop;
end $$;
create function public.change_company_default_currency(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare target public.crm_currencies; original public.crm_currencies; divisor numeric;begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),'currencies.update') or not public.has_effective_permission(auth.uid(),'settings.update') then raise exception 'Permission denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(180102,1);
 select * into target from public.crm_currencies where id=p_id for update;if not found then raise exception 'Currency unavailable' using errcode='P0002';end if;
 if target.is_default then return;end if;
 select * into original from public.crm_currencies where is_default;
 if not found then raise exception 'Default currency unavailable' using errcode='P0002';end if;
 perform 1 from public.company_settings where id=1 for update;if not found then raise exception 'Company settings unavailable' using errcode='P0002';end if;
 if (select count(*) from public.crm_currency_rates)>50000 or (select count(distinct start_date) from public.crm_currency_rates)*(select count(*) from public.crm_currencies)>50000 then raise exception 'Currency history requires background processing; no rates were changed' using errcode='54000';end if;
 divisor=target.conversion_rate;
 if divisor=0 or exists(select 1 from (select distinct start_date from public.crm_currency_rates) boundary where coalesce((select conversion_rate from public.crm_currency_rates where currency_id=target.id and start_date<=boundary.start_date order by start_date desc limit 1),target.conversion_rate)=0) then raise exception 'A currency with a zero effective rate cannot become the default. No rates changed.' using errcode='23514';end if;
 -- Approved exception: preserve all historical step-function boundaries, even with only two currencies.
 -- Snapshot before any changes. Existing dated IDs survive where the new matrix has that same key.
 insert into public.crm_currency_rebases(actor_id,old_currency,new_currency,previous_state)
 select auth.uid(),original.currency,target.currency,jsonb_build_object('currencies',(select jsonb_agg(to_jsonb(c)) from public.crm_currencies c),'dated_rates',coalesce((select jsonb_agg(to_jsonb(r)) from public.crm_currency_rates r),'[]'::jsonb));
 with boundaries as materialized(select distinct start_date from public.crm_currency_rates),matrix as materialized(
 select c.id,b.start_date,
 (case when c.is_default then 1 else coalesce((select conversion_rate from public.crm_currency_rates where currency_id=c.id and start_date<=b.start_date order by start_date desc limit 1),c.conversion_rate) end)/
 coalesce((select conversion_rate from public.crm_currency_rates where currency_id=target.id and start_date<=b.start_date order by start_date desc limit 1),target.conversion_rate) as rate
 from public.crm_currencies c cross join boundaries b where c.id<>target.id)
 insert into public.crm_currency_rates(currency_id,conversion_rate,start_date,created_by_id) select id,rate,start_date,auth.uid() from matrix
 on conflict(currency_id,start_date) do update set conversion_rate=excluded.conversion_rate;
 delete from public.crm_currency_rates where currency_id=target.id;
 update public.crm_currencies set is_default=false;
 update public.crm_currencies set conversion_rate=case when id=p_id then 1 else conversion_rate/divisor end,is_default=(id=p_id),updated_by_id=auth.uid(),updated_at=now();
 update public.company_settings set currency=target.currency where id=1;
 if not found then raise exception 'Company settings unavailable' using errcode='P0002';end if;
end $$;
create function public.company_currency_rate(p_id uuid,p_on_date date default null) returns numeric language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare result numeric;begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') or not public.has_effective_permission(auth.uid(),'currency_rates.view') then raise exception 'Permission denied' using errcode='42501';end if;
 select conversion_rate into result from public.crm_currency_rates where currency_id=p_id and start_date<=coalesce(p_on_date,current_date) order by start_date desc limit 1;
 if result is null then select conversion_rate into result from public.crm_currencies where id=p_id;end if;
 if result is null then raise exception 'Currency unavailable' using errcode='P0002';end if;return result;
end $$;
create function public.company_currency_catalog(p_date date default null) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare result jsonb;selected date;dates jsonb='[]';dated jsonb='[]';begin
 if not public.has_effective_permission(auth.uid(),'currencies.view') then raise exception 'Permission denied' using errcode='42501';end if;
 if (select count(*) from public.crm_currencies)>500 then raise exception 'Currency catalog exceeds this bounded editor' using errcode='54000';end if;
 if public.has_effective_permission(auth.uid(),'currency_rates.view') then
  selected=coalesce(p_date,(select max(start_date) from public.crm_currency_rates where start_date<=current_date),(select min(start_date) from public.crm_currency_rates));
  with distinct_dates as(select distinct start_date from public.crm_currency_rates),ranges as(select start_date,lead(start_date)over(order by start_date)-1 as end_date from distinct_dates),limited as(select * from ranges order by start_date desc limit 100)
  select coalesce(jsonb_agg(to_jsonb(limited)),'[]') into dates from limited;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'currency_id',r.currency_id,'currency',c.currency,'name',cc.name,'conversion_rate',r.conversion_rate::text,'start_date',r.start_date) order by c.currency),'[]') into dated from public.crm_currency_rates r join public.crm_currencies c on c.id=r.currency_id join public.crm_currency_codes cc on cc.code=c.currency where r.start_date=selected;
 end if;
 select jsonb_build_object('enabled',s.activate_multiple_currencies,'company_currency',s.currency,'has_history',exists(select 1 from public.crm_currency_rates),'selected_date',selected,'date_ranges',dates,'more_date_ranges',(select count(distinct start_date) from public.crm_currency_rates)>100,'dated_rows',dated,
 'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'currency',c.currency,'name',cc.name,'conversion_rate',c.conversion_rate::text,'decimal_places',c.decimal_places,'is_default',c.is_default,'is_active',c.is_active) order by c.is_default desc,c.currency),'[]') from public.crm_currencies c join public.crm_currency_codes cc on cc.code=c.currency)) into result from public.company_settings s where id=1;
 if result is null then raise exception 'Company settings unavailable' using errcode='P0002';end if;return result;
end $$;
revoke all on function public.set_multiple_currency_enabled(boolean),public.save_company_currency(uuid,text,text,integer),public.delete_company_currency(uuid),public.save_company_exchange_rates(jsonb,date),public.change_company_default_currency(uuid),public.company_currency_rate(uuid,date),public.company_currency_catalog(date) from public,anon;
grant execute on function public.set_multiple_currency_enabled(boolean),public.save_company_currency(uuid,text,text,integer),public.delete_company_currency(uuid),public.save_company_exchange_rates(jsonb,date),public.change_company_default_currency(uuid),public.company_currency_rate(uuid,date),public.company_currency_catalog(date) to authenticated;
commit;
